/**
 * Patrimonio · Dividendi — a sale takes the announced dividend with it, desktop 1440 (2026-11-23).
 *
 * What only a browser can prove: a trade saved through «Registra operazione» reaches the server's
 * reconciliation AFTER its transaction, against the real Firestore rules and indexes, and the Dividendi
 * tab re-reads the record list without a reload. A EUR stock with a baseline of 10 and an auto-generated
 * dividend announced for a future ex-date; selling the 10 before the ex-date deletes the automatic record,
 * while a hand-entered decoy on the same asset stays. The rule itself is __tests__/dividendEntitlement.test.ts.
 *
 * Data-only: the fixture is planted with the Admin SDK and removed in a loop at the start and at the end
 * (doc/guide/e2e-playwright.md § Browser-Driven E2E (Playwright)). Invented, round figures.
 */

import { test, expect } from '@playwright/test';

process.env.FIRESTORE_EMULATOR_HOST = '127.0.0.1:8080';
process.env.GCLOUD_PROJECT = 'demo-net-worth';

const UID = 'test-user-1';
const ASSET_ID = 'e2e-stock-pellicano';
const TICKER = 'PELLICANO';
const AUTO_ID = 'e2e-pellicano-auto';
const DECOY_ID = 'e2e-pellicano-manual';
const DAY_MS = 86_400_000;

test.setTimeout(240_000);

async function admin() {
  const { initializeApp, getApps } = await import('firebase-admin/app');
  const { getFirestore } = await import('firebase-admin/firestore');
  const app = getApps()[0] ?? initializeApp({ projectId: process.env.GCLOUD_PROJECT });
  return getFirestore(app);
}

/** Everything the fixture and the app wrote for the stock, so an earlier failed run leaves nothing. */
async function removeStock(db: FirebaseFirestore.Firestore) {
  for (const collection of ['assetTransactions', 'dividends', 'expenses']) {
    const rows = await db.collection(collection).where('userId', '==', UID).where('assetId', '==', ASSET_ID).get();
    for (const row of rows.docs) await row.ref.delete();
  }
  await db.collection('assets').doc(ASSET_ID).delete();
}

function announced(id: string, isAutoGenerated: boolean, exInDays: number, paidInDays: number) {
  const now = new Date();
  return {
    id,
    data: {
      userId: UID, assetId: ASSET_ID, assetTicker: TICKER, assetName: 'Pellicano Industrie', isin: 'IT0000000009',
      exDate: new Date(now.getTime() + exInDays * DAY_MS), paymentDate: new Date(now.getTime() + paidInDays * DAY_MS),
      dividendPerShare: 1, quantity: 10, grossAmount: 10, taxAmount: 2.6, netAmount: 7.4,
      grossAmountEur: 10, taxAmountEur: 2.6, netAmountEur: 7.4, exchangeRate: 1,
      currency: 'EUR', dividendType: 'ordinary', isAutoGenerated, createdAt: now, updatedAt: now,
    },
  };
}

async function plantStock(db: FirebaseFirestore.Firestore) {
  const now = new Date();
  await db.collection('assets').doc(ASSET_ID).set({
    userId: UID, ticker: TICKER, name: 'Pellicano Industrie', isin: 'IT0000000009',
    type: 'stock', assetClass: 'equity', currency: 'EUR', quantity: 10,
    averageCost: 10, averageCostEur: 10, currentPrice: 10, isLiquid: true, autoUpdatePrice: false,
    allocationRole: 'tradable', createdAt: now, updatedAt: now,
  });
  await db.collection('assetTransactions').doc(`${ASSET_ID}-baseline`).set({
    userId: UID, assetId: ASSET_ID, type: 'buy', date: new Date(2026, 0, 2, 12), quantity: 10,
    pricePerUnit: 10, priceEur: 10, isBaseline: true, createdAt: now, updatedAt: now,
  });
  // Both payments a few weeks out, inside the year the tab shows by default near December.
  for (const record of [announced(AUTO_ID, true, 15, 25), announced(DECOY_ID, false, 18, 28)]) {
    await db.collection('dividends').doc(record.id).set(record.data);
  }
}

test('a sale before the ex-date deletes the automatic announced dividend, never the hand-entered one', async ({ page }) => {
  const db = await admin();
  await removeStock(db);
  const metaRef = db.collection('assetTransactionsMeta').doc(UID);
  const plantedMeta = !(await metaRef.get()).exists;
  if (plantedMeta) {
    const now = new Date();
    await metaRef.set({ userId: UID, migratedAt: now, baselineDate: new Date(2025, 0, 1), migratedAssetCount: 0, createdAt: now, updatedAt: now });
  }
  await plantStock(db);

  try {
    // ── 1. Dividendi before: both records of the stock are announced ──
    await page.goto('/dashboard/cashflow?tab=dividends', { waitUntil: 'load' });
    const stockRows = page.locator('tr').filter({ hasText: TICKER }).filter({ hasText: 'Attesa' });
    await expect(stockRows).toHaveCount(2, { timeout: 90_000 });

    // ── 2. Sell the 10 through the trade form ──
    await page.goto('/dashboard/assets', { waitUntil: 'load' });
    const row = page.getByRole('row').filter({ hasText: 'Pellicano' });
    await expect(row).toBeVisible({ timeout: 90_000 });
    await row.getByRole('button', { name: /^Registra operazione su / }).click();
    const dialog = page.getByRole('dialog');
    await dialog.getByRole('radio', { name: 'Vendi' }).click();
    await dialog.locator('#trade-quantity').fill('10');
    await dialog.locator('#trade-price').fill('10');
    await dialog.getByRole('button', { name: 'Registra operazione' }).click();
    await expect(dialog).toBeHidden({ timeout: 60_000 });
    await expect(page.getByText('1 dividendo annunciato eliminato', { exact: false })).toBeVisible({ timeout: 30_000 });

    // ── 3. On the emulator: the automatic record is gone, the decoy untouched ──
    expect((await db.collection('dividends').doc(AUTO_ID).get()).exists).toBe(false);
    const decoy = await db.collection('dividends').doc(DECOY_ID).get();
    expect(decoy.exists).toBe(true);
    expect(decoy.data()?.quantity).toBe(10);

    // ── 4. Dividendi after, with no reload of the cache: one announced row left ──
    await page.goto('/dashboard/cashflow?tab=dividends', { waitUntil: 'load' });
    await expect(stockRows).toHaveCount(1, { timeout: 90_000 });
  } finally {
    await removeStock(db);
    if (plantedMeta) await metaRef.delete();
  }
});
